import pageCounts from "../generated/transaction-documents.json";
import { fromCms } from "./cms";

export type TransactionDocument = {
  slug: string;
  title: string;
  description: string;
  pages: number;
};

export type TransactionDocumentDetails = Omit<TransactionDocument, "pages">;

/**
 * Programme documents supplied for on-screen reading only.
 * Page images are generated by `scripts/render-transaction-documents.mjs`.
 * The source PDFs are not published.
 */
export const LOCAL_TRANSACTION_DOCUMENTS: TransactionDocumentDetails[] = [
  {
    slug: "assignment-agreement",
    title: "Assignment Agreement",
    description:
      "Documents the assignment of specified cocoa receivables to Cocoa Capital PLC under the Programme.",
  },
  {
    slug: "financing-agreement",
    title: "Financing Agreement",
    description:
      "Governs the financing provided by Cocoa Capital PLC to COCOBOD, including repayment terms and the approved use of funds.",
  },
  {
    slug: "trust-deed",
    title: "Trust Deed",
    description:
      "Sets out the duties of the Note Trustees under the Programme for the benefit of Noteholders.",
  },
];

export const TRANSACTION_DOCUMENTS: TransactionDocument[] = fromCms(
  "transactionDocuments",
  LOCAL_TRANSACTION_DOCUMENTS
).map((document) => ({
  ...document,
  pages: (pageCounts as Record<string, number>)[document.slug] ?? 0,
}));

export function getTransactionDocument(
  slug: string
): TransactionDocument | undefined {
  return TRANSACTION_DOCUMENTS.find((document) => document.slug === slug);
}

export { transactionDocumentPageSrc } from "./transaction-document-pages";
